import {createEditor} from './editor';
import {events} from './events';
import type {Document, Edit} from './model';
export function mount(initial: Document, render: (value: Document) => void) { const editor = createEditor(initial, render); const history: Edit[] = []; const record = (edit: Edit) => { const result = editor.dispatch(edit); if (result.ok) history.push(edit); return result; }; return {handlers: events(record), history, snapshot: editor.snapshot}; }

